import {backend} from './backend.js';
import {escape as e} from './store.js';
let recoveryError='';
export function forgotPage(){return `<section class="card auth-card"><span class="eyebrow">ACCOUNT HELP</span><h2>Forgot your password?</h2><p class="muted">Enter the email address you used to register. We’ll send a password-reset link.</p><form id="forgot-form"><label for="recovery-email">Email</label><input id="recovery-email" name="email" type="email" autocomplete="email" required><p id="recovery-status" class="muted" role="status"></p><div class="actions"><button class="btn primary">Send reset link</button><button class="btn" type="button" data-route="login">Back to login</button></div></form></section>`;}
export function resetPage(){return `<section class="card auth-card"><span class="eyebrow">ACCOUNT HELP</span><h2>Choose a new password</h2>${backend.recoveryReady()?`<form id="reset-form"><label for="new-password">New password</label><input id="new-password" name="password" type="password" minlength="8" maxlength="200" autocomplete="new-password" required><label for="confirm-password">Confirm password</label><input id="confirm-password" name="confirm" type="password" minlength="8" maxlength="200" autocomplete="new-password" required><p id="reset-status" class="muted" role="status"></p><button class="btn primary">Update password</button></form>`:`<p class="muted">${e(recoveryError||'Open the password-reset link sent to your email to set a new password.')}</p><button class="btn primary" data-route="forgot">Request a fresh link</button>`}</section>`;}
export async function handleRecoveryLink(){const params=new URLSearchParams(location.hash.slice(1));if(params.get('type')!=='recovery')return false;const access=params.get('access_token'),refresh=params.get('refresh_token');history.replaceState(null,'',location.pathname+location.search+'#reset');try{if(!access||!refresh)throw new Error('This recovery link is incomplete. Request a fresh link.');await backend.acceptRecovery(access,refresh,Number(params.get('expires_in'))||3600);}catch(err){recoveryError=err.message;}return true;}
export function bindRecovery(ui){const forgot=document.querySelector('#forgot-form');if(forgot)forgot.onsubmit=async event=>{event.preventDefault();const button=forgot.querySelector('button'),status=document.querySelector('#recovery-status');button.disabled=true;try{await backend.requestRecovery(new FormData(forgot).get('email').trim(),location.origin+location.pathname+'#reset');status.textContent='If this address has an account, a reset link will arrive shortly. Check your inbox and spam folder.';}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};const reset=document.querySelector('#reset-form');if(reset)reset.onsubmit=async event=>{event.preventDefault();const form=new FormData(reset),status=document.querySelector('#reset-status'),button=reset.querySelector('button');if(form.get('password')!==form.get('confirm')){status.textContent='The passwords do not match.';return;}button.disabled=true;try{await backend.resetPassword(form.get('password'));location.hash='login';ui.toast('Password updated. Log in with your username and new password.');}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};}
